#include "elevator.h"
void elevator_init(Elevator*e){e->state=OFF;e->current=2;e->target=2;}static void request(Elevator*e,int f){e->target=f;if(f>e->current)e->state=MOVING_UP;else if(f<e->current)e->state=MOVING_DOWN;else e->state=STOPPED;}void elevator_event(Elevator*e,Event v){if(e->state==OFF){if(v==POWER_ON)e->state=FLOOR2;return;}if(v==CALL_2)request(e,2);else if(v==CALL_3)request(e,3);else if(v==CALL_4)request(e,4);else if(v==CAB_2||v==CAB_3||v==CAB_4){e->current=v==CAB_2?2:v==CAB_3?3:4;if(e->current==e->target)e->state=STOPPED;}else if(e->state==STOPPED&&v==TIMER)e->state=DOOR_OPENING;else if(e->state==DOOR_OPENING&&v==DOOR_IS_OPEN)e->state=DOOR_OPEN;else if(e->state==DOOR_OPEN&&v==TIMER)e->state=DOOR_CLOSING;else if(e->state==DOOR_CLOSING&&v==DOOR_IS_OBSTRUCTED)e->state=DOOR_OBSTRUCTED;else if(e->state==DOOR_OBSTRUCTED&&v==RETRY_OPEN)e->state=DOOR_OPENING;else if(e->state==DOOR_CLOSING&&v==DOOR_IS_CLOSED)e->state=DOOR_CLOSED;}const char*state_name(State s){static const char*n[]={"OFF","IDLE","FLOOR2","FLOOR3","FLOOR4","MOVING_UP","MOVING_DOWN","STOPPED","DOOR_OPENING","DOOR_OPEN","DOOR_CLOSING","DOOR_CLOSED","DOOR_OBSTRUCTED"};return n[s];}
